var t=`0819-oshifima`;var n=`world-0819`;var s=`NA`;var a=`southern-africa`;var r=4;var o=40;var m={en:`Oshifima`,ua:`Ошіфіма`};var l={en:`Oshifima is a Namibia dish made with cornmeal, peanut butter. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Ошіфіма, страва кухні країни Намібія. Основні складники: кукурудзяна крупа дрібного помелу, арахісова паста. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var g=[{en:`Cook the listed ingredients in simmering water for about 8 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 8 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:8,i:[[`water`,950,`ml`],[`table-salt`,5,`g`]]},{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 25 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 25 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:25,i:[[`cornmeal`,480,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`unsalted-butter`,25,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`peanut-butter`,65,`g`]]}];var u={slug:t,id:n,country:`NA`,region:a,servings:4,minutes:40,title:m,text:l,steps:g};export{s as country,u as default,n as id,o as minutes,a as region,r as servings,t as slug,g as steps,l as text,m as title};